package com.isecure.core

import com.isecure.core.crypto.VaultService
import com.isecure.core.model.EncryptedVaultEnvelope
import com.isecure.core.model.VaultPayload
import java.io.File
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

/**
 * Cross-implementation vectors: envelope.json + payload.json + meta.json
 * in desktop/vectors/ are generated by the REAL TypeScript
 * implementation (vectors/generate_vectors.ts) — including a Persian
 * master password and Persian entry content, at the production 600,000
 * PBKDF2 iterations. This test proves the Kotlin core decrypts what the
 * shipped app encrypts, and writes envelope-kotlin.json so
 * vectors/verify_kotlin_envelope.ts can prove the reverse direction.
 */
class CryptoVectorTest {
    private val vectorsDir = File("vectors")
    private val plainJson = Json { ignoreUnknownKeys = true }

    private fun readJson(name: String): JsonObject =
        plainJson.parseToJsonElement(vectorsDir.resolve(name).readText()).jsonObject

    @Test
    fun decryptsTypeScriptEnvelope() {
        val secret = readJson("meta.json").getValue("masterSecret").jsonPrimitive.content
        val envelope = VaultService.json.decodeFromString(
            EncryptedVaultEnvelope.serializer(),
            vectorsDir.resolve("envelope.json").readText(),
        )
        val payload = VaultService.decryptEnvelope(envelope, secret)
        val expected = plainJson.parseToJsonElement(
            vectorsDir.resolve("payload.json").readText(),
        )
        val actual = VaultService.json.encodeToJsonElement(
            VaultPayload.serializer(),
            payload,
        )
        assertEquals(expected, actual)
    }

    @Test
    fun rejectsWrongMasterSecret() {
        val envelope = VaultService.json.decodeFromString(
            EncryptedVaultEnvelope.serializer(),
            vectorsDir.resolve("envelope.json").readText(),
        )
        assertFailsWith<Exception> {
            VaultService.decryptEnvelope(envelope, "definitely-the-wrong-secret")
        }
    }

    @Test
    fun encryptsEnvelopeForTypeScriptToOpen() {
        val secret = readJson("meta.json").getValue("masterSecret").jsonPrimitive.content
        val payload = VaultService.json.decodeFromString(
            VaultPayload.serializer(),
            vectorsDir.resolve("payload.json").readText(),
        )
        val envelope = VaultService.encryptPayload(payload, secret)
        vectorsDir.resolve("envelope-kotlin.json").writeText(
            VaultService.json.encodeToString(
                EncryptedVaultEnvelope.serializer(),
                envelope,
            ),
        )
        // Self-check: our own decrypt must round-trip too.
        val back = VaultService.decryptEnvelope(envelope, secret)
        assertEquals(payload, back)
    }
}
